// Centre de répartition des événements de rendez-vous
// Le backend MedSecretariat reste la source de vérité ; ce workflow
// prépare la synchronisation emails / notifications / Google Calendar.
// Les types correspondent à l'enum NotificationType du backend.
const src = $json.body || $json;
const event = src.event || 'appointment.unknown';
const t = {
  id: src.appointment_id,
  patientId: src.patient_id,
  patientName: src.patient_name || 'Patient',
  doctorId: src.doctor_id,
  scheduledAt: src.scheduled_at,
  proposedAt: src.proposed_at || null,
  duration: src.duration,
  status: src.status,
  reason: src.reason || null,
};

const messages = {
  'appointment.requested': {
    type: 'system',
    subject: 'Demande de rendez-vous envoyée',
    body: `Bonjour ${t.patientName}, votre demande de rendez-vous du ${t.scheduledAt} a bien été transmise au secrétariat.`,
  },
  'appointment.confirmed': {
    type: 'appointment_confirmed',
    subject: 'Rendez-vous confirmé',
    body: `Bonjour ${t.patientName}, votre rendez-vous du ${t.scheduledAt} est confirmé.`,
  },
  'appointment.rejected': {
    type: 'appointment_rejected',
    subject: 'Rendez-vous refusé',
    body: `Bonjour ${t.patientName}, votre demande de rendez-vous a été refusée.${t.reason ? ' Motif : ' + t.reason : ''}`,
  },
  'appointment.rescheduled': {
    type: 'appointment_rescheduled',
    subject: "Proposition d'un autre créneau",
    body: `Bonjour ${t.patientName}, le secrétariat vous propose le créneau ${t.proposedAt || ''}.`,
  },
  'appointment.cancelled': {
    type: 'system',
    subject: 'Rendez-vous annulé',
    body: `Bonjour ${t.patientName}, votre rendez-vous du ${t.scheduledAt} a été annulé.`,
  },
};

const msg = messages[event] || {
  type: 'system',
  subject: 'Événement de rendez-vous',
  body: JSON.stringify(src),
};
return [{ ...t, event, ...msg }];

// Prépare l'appel au backend pour créer la notification patient (in-app)
const item = $('Préparer les notifications').first().json;
const dateStr = item.scheduledAt ? String(item.scheduledAt).slice(0, 10) : '';
return [{
  patient_id: item.patientId,
  title: item.subject,
  message: item.body || item.message,
  type: item.type,
  related_entity_id: item.id,
  related_entity_type: 'appointment',
}];
